using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
class ShimUnityTransform {static void Main(string[] args){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(args[0])));using(var input=ModuleDefinition.ReadModule(args[0],new ReaderParameters{AssemblyResolver=resolver})){var method=input.GetType("UnityEngine.Component").Methods.Single(m=>m.Name=="get_transform"&&m.Parameters.Count==0);if((method.ImplAttributes&MethodImplAttributes.InternalCall)==0||method.HasBody)throw new Exception("Unexpected Unity getter");method.ImplAttributes&=~(MethodImplAttributes.InternalCall|MethodImplAttributes.CodeTypeMask|MethodImplAttributes.Unmanaged);method.Body=new MethodBody(method);method.Body.Instructions.Add(Instruction.Create(OpCodes.Ldnull));method.Body.Instructions.Add(Instruction.Create(OpCodes.Throw));input.Write(args[1]);Console.WriteLine("Test-only UnityEngine.Component.get_transform stub: throws if invoked; actual game assembly unchanged.");}}}
